  SELECT id INTO v_cat_id FROM categories WHERE slug = 'laptops-accessories' LIMIT 1;
  SELECT id INTO v_brand_id FROM brands WHERE slug = 'asus' LIMIT 1;

  INSERT INTO products (name, slug, description, category_id, brand_id, is_active)
  VALUES (
    'Asus TUF A15 Gaming Laptop (AMD Ryzen 7/ 16GB RAM/ 512GB SSD/ 15.6 Inch (39.62 cm) FHD Display/ 4GB-NVIDIA GeForce RTX 3050 Graphics/ Windows 11/ MS-Office) FA506NCQ-IN081WS',
    'asus-tuf-a15-gaming-laptop-amd-ryzen-7-16gb-ram-512gb-ssd-156-inc-260037',
