BEGIN
  SELECT id INTO v_cat_id FROM categories WHERE slug = 'laptops-accessories' LIMIT 1;
  SELECT id INTO v_brand_id FROM brands WHERE slug = 'lenovo' LIMIT 1;

  INSERT INTO products (name, slug, description, category_id, brand_id, is_active)
  VALUES (
    'Lenovo Yoga 7i 2-in-1 Aura Edition Laptop (Intel Core Ultra 5/ 16GB RAM/ 512GB SSD/ 14 Inch (35.56 cm) WUXGA OGS, 10-point Multi-touch Display/ Intel Graphics/ Windows 11/ MS-Office/ Copilot+ PC) 83TC005MIN',
