  RETURNING id INTO v_prod_id;

  IF v_prod_id IS NULL THEN
    SELECT id INTO v_prod_id FROM products WHERE slug = 'lenovo-yoga-7i-2-in-1-aura-edition-laptop-intel-core-ultra-5-16gb-ra-259174' LIMIT 1;
  END IF;

  INSERT INTO product_variants (
    product_id, sku, name, price_cents, compare_at_price_cents, is_serialized
  )
  VALUES (
    v_prod_id,
