  v_cat_id UUID;
  v_brand_id UUID;
  v_prod_id UUID;
  v_var_id UUID;
BEGIN
  SELECT id INTO v_cat_id FROM categories WHERE slug = 'laptops-accessories' LIMIT 1;
  SELECT id INTO v_brand_id FROM brands WHERE slug = 'asus' LIMIT 1;

  INSERT INTO products (name, slug, description, category_id, brand_id, is_active)
  VALUES (
    'Asus Vivobook 15 AI Laptop (Intel Core 5/ 8GB RAM/ 512GB SSD/ 15.6 Inch (39.62 cm) FHD Display/ Intel Graphics/ Windows 11/ MS-Office) X1504MA-BQ832WS',
    'asus-vivobook-15-ai-laptop-intel-core-5-8gb-ram-512gb-ssd-156-inc-260035',
    'Asus Vivobook 15 AI Laptop (Intel Core 5/ 8GB RAM/ 512GB SSD/ 15.6 Inch (39.62 cm) FHD Display/ Intel Graphics/ Windows 11/ MS-Office) X1504MA-BQ832WS. Clean high-resolution catalog entry imported directly from official retail specs.',
    v_cat_id,
    v_brand_id,
    true
  )
  ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name
  RETURNING id INTO v_prod_id;

  IF v_prod_id IS NULL THEN
    SELECT id INTO v_prod_id FROM products WHERE slug = 'asus-vivobook-15-ai-laptop-intel-core-5-8gb-ram-512gb-ssd-156-inc-260035' LIMIT 1;
  END IF;

  INSERT INTO product_variants (
    product_id, sku, name, price_cents, compare_at_price_cents, is_serialized
  )
  VALUES (
    v_prod_id,
    'VS-LAP-260035',
    'Asus Vivobook 15 AI Laptop (Intel Core 5/ 8GB RAM/ 512GB SSD/ 15.6 Inch (39.62 cm) FHD Display/ Intel Graphics/ Windows 11/ MS-Office) X1504MA-BQ832WS',
    8999000,
    1379903500,
    true
  )
  ON CONFLICT (sku) DO UPDATE SET
    price_cents = EXCLUDED.price_cents,
    compare_at_price_cents = EXCLUDED.compare_at_price_cents
