  SELECT id INTO v_brand_id FROM brands WHERE slug = 'hp' LIMIT 1;

  INSERT INTO products (name, slug, description, category_id, brand_id, is_active)
  VALUES (
    'HP OmniBook 3 AI Laptop (Intel Core Ultra 5/ 16GB RAM/ 512GB SSD/ 14 Inch (35.56 cm) 2K Display/ Intel Graphics/ Windows 11) 14-ht0052TU',
    'hp-omnibook-3-ai-laptop-intel-core-ultra-5-16gb-ram-512gb-ssd-14-i-257080',
    'HP OmniBook 3 AI Laptop (Intel Core Ultra 5/ 16GB RAM/ 512GB SSD/ 14 Inch (35.56 cm) 2K Display/ Intel Graphics/ Windows 11) 14-ht0052TU. Clean high-resolution catalog entry imported directly from official retail specs.',
