DO $$
DECLARE
  v_cat_id UUID;
  v_brand_id UUID;
  v_prod_id UUID;
  v_var_id UUID;
BEGIN
  SELECT id INTO v_cat_id FROM categories WHERE slug = 'laptops-accessories' LIMIT 1;
  SELECT id INTO v_brand_id FROM brands WHERE slug = 'apple' LIMIT 1;

  INSERT INTO products (name, slug, description, category_id, brand_id, is_active)
  VALUES (
    'Apple MacBook Neo A18 Pro chip (8GB RAM/ 256GB SSD/ 13" Liquid Retina Display/ 6 core CPU and 5 core GPU/ Silver) - MHFA4HN/A',
    'apple-macbook-neo-a18-pro-chip-8gb-ram-256gb-ssd-13-liquid-retina-1789242988095',
    'Apple MacBook Neo A18 Pro chip (8GB RAM/ 256GB SSD/ 13" Liquid Retina Display/ 6 core CPU and 5 core GPU/ Silver) - MHFA4HN/A. Clean high-resolution catalog entry imported directly from official retail specs.',
    v_cat_id,
    v_brand_id,
    true
  )
  ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name
