  INSERT INTO products (name, slug, description, category_id, brand_id, is_active)
  VALUES (
    'Apple MacBook Pro M5 Pro Chip (24GB RAM/ 2TB SSD/ 14" (35.56 cm) Liquid Retina XDR Display/ 15-core CPU/ 16-core GPU/ macOS/ Space Black) MJLW4HN/A',
    'apple-macbook-pro-m5-pro-chip-24gb-ram-2tb-ssd-14-3556-cm-liqui-258926',
    'Apple MacBook Pro M5 Pro Chip (24GB RAM/ 2TB SSD/ 14" (35.56 cm) Liquid Retina XDR Display/ 15-core CPU/ 16-core GPU/ macOS/ Space Black) MJLW4HN/A. Clean high-resolution catalog entry imported directly from official retail specs.',
    v_cat_id,
    v_brand_id,
    true
  )
  ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name
