  IF v_prod_id IS NULL THEN
    SELECT id INTO v_prod_id FROM products WHERE slug = 'apple-macbook-pro-m5-pro-chip-24gb-ram-2tb-ssd-14-3556-cm-liqui-258926' LIMIT 1;
